"""Exact, bounded bookkeeping for a subgroup generated by permutations.

The public ``finite_group_structure`` function accepts either explicit cycle
notation or one exact name from a closed vocabulary of standard small groups;
the named form is expanded to explicit generators before the same closure path.
It returns the repository's ``Evidence`` contract.  Every value is an integer or
a canonical string; the producer never changes a permutation into a float and
never claims that the input models the intent of an original problem.

The group is obtained by explicit closure under function composition.  The
closure is deliberately small (at most 600 elements) so both the producer and
the independent output audit can enumerate every element and conjugacy class.
"""

from __future__ import annotations

import json
import math
import re

from math_families.core.evidence import Evidence

from .output_checks.common import bound, require

GROUP_SCHEMA = "finite-group-structure-v1"
GROUP_OPERATION = "GROUP_STRUCTURE"

MIN_DEGREE = 2
MAX_DEGREE = 8
MIN_GENERATORS = 1
MAX_GENERATORS = 4
MAX_CLOSURE_ELEMENTS = 600
MAX_GENERATOR_TEXT = 160
MAX_NAMED_GROUP_TEXT = 8
MAX_NAMED_CYCLIC_ORDER = 12

# A closed vocabulary of standard small groups.  Each entry is expanded to an
# explicit generating set on (at least) the smallest faithful permutation
# degree used by this tool; the existing closure/enumeration path then runs
# unchanged.  C_n is accepted as an alias of Z_n by ``_named_group_expansion``.
_NAMED_GROUP_GENERATORS = {
    "S3": (3, ("(12)", "(123)")),
    "S4": (4, ("(12)", "(1234)")),
    "A4": (4, ("(123)", "(124)")),
    "A5": (5, ("(12345)", "(123)")),
    "D8": (4, ("(1234)", "(13)")),
    "D10": (5, ("(12345)", "(25)(34)")),
}
_NAMED_GROUP_PATTERN = re.compile(r"(S|A|D|Z|C)_?([2-9]|1[0-2])")

TOOL_SIGNATURES = {
    "finite_group_structure": ("generators", "named_group", "degree"),
}


def _cycle_tokens(text):
    """Parse a product of cycles into integer lists without evaluating text."""
    require(
        type(text) is str and 1 <= len(text) <= MAX_GENERATOR_TEXT,
        "generator: bounded cycle-notation string required",
    )
    source = text.strip()
    require(source, "generator: nonempty cycle notation required")
    cycles = []
    position = 0
    while position < len(source):
        if source[position].isspace():
            position += 1
            continue
        require(
            source[position] == "(",
            "generator: product of disjoint cycles required",
        )
        close = source.find(")", position + 1)
        require(close != -1, "generator: unterminated cycle")
        body = source[position + 1 : close]
        require("(" not in body, "generator: nested cycle is not allowed")
        stripped = body.strip()
        if stripped:
            if "," in stripped:
                parts = [part.strip() for part in stripped.split(",")]
                require(
                    all(parts),
                    "generator: empty point between commas is not allowed",
                )
                tokens = [token for part in parts for token in part.split()]
            elif re.search(r"\s", stripped):
                tokens = stripped.split()
            else:
                tokens = list(stripped)
            require(
                all(re.fullmatch(r"[0-9]+", token) for token in tokens),
                "generator: cycle points must be positive integers separated by commas or spaces",
            )
            cycles.append([int(token) for token in tokens])
        else:
            cycles.append([])
        position = close + 1
    require(cycles, "generator: product of disjoint cycles required")
    return cycles


def _generator_permutation(cycles, degree):
    permutation = list(range(degree))
    seen = set()
    for cycle in cycles:
        # A one-point cycle is a fixed point.  Repeating a point across cycles
        # would make the written product non-disjoint.
        require(
            len(set(cycle)) == len(cycle),
            "generator: each point may occur only once across disjoint cycles",
        )
        for point in cycle:
            require(
                1 <= point <= degree,
                "generator: point outside the declared degree",
            )
            require(point not in seen, "generator: cycles must be disjoint")
            seen.add(point)
        if len(cycle) > 1:
            for left, right in zip(cycle, cycle[1:] + cycle[:1]):
                permutation[left - 1] = right - 1
    require(
        len(set(permutation)) == degree,
        "generator: resulting map is not a permutation",
    )
    return tuple(permutation)


def _canonical_cycle_notation(permutation):
    seen = set()
    cycles = []
    for start in range(len(permutation)):
        if start in seen:
            continue
        cycle = []
        point = start
        while point not in seen:
            seen.add(point)
            cycle.append(point + 1)
            point = permutation[point]
        if len(cycle) > 1:
            smallest = cycle.index(min(cycle))
            cycle = cycle[smallest:] + cycle[:smallest]
            cycles.append(cycle)
    cycles.sort(key=lambda cycle: cycle[0])
    if not cycles:
        return "()"
    return "".join("(" + "".join(str(point) for point in cycle) + ")" for cycle in cycles)


def _named_group_expansion(value):
    """Expand one exact vocabulary name to a canonical name and generators."""
    require(
        type(value) is str and 1 <= len(value.strip()) <= MAX_NAMED_GROUP_TEXT,
        "named_group: bounded group-name string required",
    )
    match = _NAMED_GROUP_PATTERN.fullmatch(value.strip().upper())
    require(match is not None, "named_group: unsupported group name")
    family, order_text = match.groups()
    canonical = family + order_text
    if canonical in _NAMED_GROUP_GENERATORS:
        degree, generators = _NAMED_GROUP_GENERATORS[canonical]
        return canonical, degree, generators
    # Only the cyclic families are generated from the written order.  Every
    # other unlisted spelling (including S5) is outside the closed vocabulary.
    require(family in {"Z", "C"}, "named_group: unsupported group name")
    order = int(order_text)
    cycle = "(" + ",".join(str(point) for point in range(1, order + 1)) + ")"
    return canonical, order, (cycle,)


def _normalize_permutation_generators(generators, declared, max_degree=MAX_DEGREE):
    """Validate explicit permutation generators and freeze their canonical form."""
    require(type(generators) is list, "generators: JSON array required")
    require(
        len(generators) >= MIN_GENERATORS,
        "generators: at least one generator required",
    )
    bound(
        len(generators) <= MAX_GENERATORS,
        "generators: at most 4 explicit permutations",
    )
    require(
        all(type(generator) is str for generator in generators),
        "generators: every generator must be a cycle-notation string",
    )

    parsed = [_cycle_tokens(generator) for generator in generators]
    if declared is not None:
        require(
            type(declared) is int and not isinstance(declared, bool),
            "degree: integer required; no implicit coercion",
        )
        bound(
            MIN_DEGREE <= declared <= max_degree,
            f"degree: 2 <= degree <= {max_degree}",
        )
        degree = declared
    else:
        moved = [
            point
            for cycles in parsed
            for cycle in cycles
            if len(cycle) > 1
            for point in cycle
        ]
        # Without an explicit degree the largest moved point determines the
        # common permutation domain.  The identity is valid on every domain, so
        # its canonical minimal representative uses the minimum allowed degree.
        degree = max(moved, default=MIN_DEGREE)
        bound(
            degree <= max_degree,
            f"degree inferred from the largest moved point must be <= {max_degree}",
        )
        require(
            degree >= MIN_DEGREE,
            f"degree: 2 <= degree <= {max_degree}",
        )

    permutations = [
        _generator_permutation(cycles, degree) for cycles in parsed
    ]
    # Enforce the closure cap during input preflight as well as in the
    # producer, so an oversized group is a fixed out-of-scope refusal rather
    # than an exception raised after execution starts.
    _closure(permutations, degree)
    canonical = [_canonical_cycle_notation(permutation) for permutation in permutations]
    return {
        "degree": degree,
        "generator_count": len(permutations),
        "generators": canonical,
        "generator_images": [list(permutation) for permutation in permutations],
    }


def normalize_group(args):
    """Validate either input form and freeze one canonical permutation group."""
    require(type(args) is dict, "finite-group arguments must be an object")
    require(
        set(args) <= {"generators", "degree", "named_group"},
        "finite-group arguments may contain only generators, named_group and optional degree",
    )
    has_generators = "generators" in args
    has_named_group = "named_group" in args
    require(
        has_generators != has_named_group,
        "finite-group arguments require exactly one of generators or named_group",
    )
    if has_named_group:
        require(
            set(args) == {"named_group"},
            "named_group form accepts only the named_group field",
        )
        group_name, degree, generators = _named_group_expansion(args["named_group"])
        normalized = _normalize_permutation_generators(
            list(generators), degree, max_degree=MAX_NAMED_CYCLIC_ORDER
        )
        normalized["input_mode"] = "named_group"
        normalized["group_name"] = group_name
        return normalized
    normalized = _normalize_permutation_generators(
        args["generators"], args.get("degree")
    )
    normalized["input_mode"] = "generators"
    return normalized


def _compose(left, right):
    """Function composition left after right, on zero-based images."""
    return tuple(left[right[index]] for index in range(len(left)))


def _inverse(permutation):
    inverse = [0] * len(permutation)
    for index, image in enumerate(permutation):
        inverse[image] = index
    return tuple(inverse)


def _element_order(permutation):
    seen = set()
    order = 1
    for start in range(len(permutation)):
        if start in seen:
            continue
        length = 0
        point = start
        while point not in seen:
            seen.add(point)
            length += 1
            point = permutation[point]
        order = math.lcm(order, length)
    return order


def _closure(generators, degree):
    identity = tuple(range(degree))
    elements = {identity}
    frontier = [identity]
    while frontier:
        current = frontier.pop()
        for generator in generators:
            product = _compose(current, generator)
            if product in elements:
                continue
            elements.add(product)
            bound(
                len(elements) <= MAX_CLOSURE_ELEMENTS,
                "generated subgroup exceeds the 600-element closure cap",
            )
            frontier.append(product)
    return elements


def group_payload(normalized):
    degree = normalized["degree"]
    generators = [tuple(image) for image in normalized["generator_images"]]
    elements = _closure(generators, degree)
    order = len(elements)
    ordered_elements = sorted(elements)

    orders = {element: _element_order(element) for element in ordered_elements}
    order_counts = {}
    for value in orders.values():
        order_counts[value] = order_counts.get(value, 0) + 1
    element_orders = {
        str(value): order_counts[value] for value in sorted(order_counts)
    }
    exponent = 1
    for value in order_counts:
        exponent = math.lcm(exponent, value)

    center = [
        element
        for element in ordered_elements
        if all(
            _compose(element, other) == _compose(other, element)
            for other in ordered_elements
        )
    ]

    remaining = set(ordered_elements)
    classes = []
    while remaining:
        element = min(remaining)
        orbit = {
            _compose(_compose(conjugate, element), _inverse(conjugate))
            for conjugate in ordered_elements
        }
        representative = min(orbit, key=_canonical_cycle_notation)
        classes.append(
            {
                "size": len(orbit),
                "representative": _canonical_cycle_notation(representative),
                "element_order": orders[representative],
            }
        )
        remaining -= orbit
    classes.sort(key=lambda row: row["representative"])

    payload = {
        "schema": GROUP_SCHEMA,
        "operation": GROUP_OPERATION,
        "input_mode": normalized["input_mode"],
        "degree": degree,
        "generator_count": normalized["generator_count"],
        "order": order,
        "is_abelian": len(center) == order,
        "is_cyclic": any(orders[element] == order for element in ordered_elements),
        "exponent": exponent,
        "center_size": len(center),
        "element_orders": element_orders,
        "conjugacy_classes": classes,
    }
    if "group_name" in normalized:
        payload["group_name"] = normalized["group_name"]
    return payload


def finite_group_structure(generators=None, degree=None, named_group=None):
    args = {}
    if generators is not None:
        args["generators"] = generators
    if degree is not None:
        args["degree"] = degree
    if named_group is not None:
        args["named_group"] = named_group
    normalized = normalize_group(args)
    payload = group_payload(normalized)
    return Evidence(
        value=payload,
        certificate=json.dumps(
            {
                "schema": GROUP_SCHEMA,
                "input_mode": normalized["input_mode"],
                "group_name": normalized.get("group_name"),
                "degree": normalized["degree"],
                "generators": normalized["generators"],
                "generator_images": normalized["generator_images"],
                "enumerated_elements": payload["order"],
                "element_order_distribution": payload["element_orders"],
                "method": (
                    "breadth-first closure under exact permutation composition; "
                    "hard cap 600 elements"
                ),
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ),
        self_check=(
            "self_check: explicit closure contains the identity and is closed "
            "under composition and inversion; every element order is the lcm "
            "of its disjoint cycle lengths; conjugacy orbits partition the "
            f"enumerated {payload['order']} elements"
        ),
        feasibility="ok",
        complexity_bound=(
            "at most 4 generators, explicit degree <= 8 (named cyclic groups "
            "up to degree 12), closure <= 600 elements; "
            "O(600^2 * degree) exact integer permutation operations"
        ),
    )


TOOL_FUNCTIONS = {
    "finite_group_structure": finite_group_structure,
}


def call_tool(name, args):
    """Execute the finite-group tool and return the bridge's ToolEvidence shape."""
    from math_families.bridge.evidence_bridge import to_tool_evidence_dict

    evidence = TOOL_FUNCTIONS[name](**args)
    return to_tool_evidence_dict(evidence, method=name)
